  console.log(`\n${cat.toUpperCase()} (${catProjects.length})`);
  console.log('─'.repeat(50));

  const statuses = {};
  catProjects.forEach(p => {
    statuses[p.status] = (statuses[p.status] || 0) + 1;
  });

  console.log('상태: ' + Object.entries(statuses).map(([s, c]) => `${s}(${c})`).join(', '));
  console.log('\n프로젝트:');

  catProjects
    .sort((a, b) => a.name.localeCompare(b.name))
    .slice(0, 15)
    .forEach(p => {
      const status = p.status === 'active' ? '✅' : p.status === 'completed' ? '✔️' : '📍';
      console.log(`  ${status} ${p.name}`);
    });

  if (catProjects.length > 15) {
    console.log(`  ... 외 ${catProjects.length - 15}개`);
  }
});

// 3. 데이터 무결성 체크
console.log('\n\n🔍 데이터 무결성 검사\n');

let issues = 0;

projects.forEach((p, idx) => {
  if (!p.name) {
    console.log(`❌ [${idx}] name 필드 누락`);
    issues++;
  }
